mapper.select:
SELECT course_id, sec_id, semester, year, building, room_number, time_slot_id
FROM section
WHERE course_id = #{courseId} AND sec_id = #{secId}
  AND semester = #{semester} AND year = #{year}

mapper.update:
UPDATE section
SET building = #{building}, room_number = #{roomNumber}, time_slot_id = #{timeSlotId}
WHERE course_id = #{courseId} AND sec_id = #{secId}
  AND semester = #{semester} AND year = #{year}

mapper.delete:
DELETE FROM section
WHERE course_id = #{courseId} AND sec_id = #{secId}
  AND semester = #{semester} AND year = #{year}

mapper.select:
SELECT COUNT(*)
FROM section s
JOIN time_slot ts ON ts.time_slot_id = s.time_slot_id
JOIN time_slot nt ON nt.time_slot_id = #{timeSlotId}
WHERE s.semester = #{semester} AND s.year = #{year}
  AND s.building = #{building} AND s.room_number = #{roomNumber}
  AND ts.day = nt.day
  AND ts.start_time < nt.end_time AND nt.start_time < ts.end_time
  AND NOT (s.course_id = #{courseId} AND s.sec_id = #{secId}
           AND s.semester = #{semester} AND s.year = #{year})

SELECT COUNT(*) FROM takes
WHERE course_id = #{courseId} AND sec_id = #{secId}
  AND semester = #{semester} AND year = #{year}
